import 'package:equatable/equatable.dart';\n\nimport 'job.dart';\n\nclass JobApplication extends Equatable {\n  final String id;\n  final String status; // applied, reviewed, shortlisted, rejected, hired\n  final DateTime? appliedAt;\n  final DateTime? updatedAt;\n  final Job? job;\n  final String? coverLetter;\n\n  const JobApplication({\n    required this.id,\n    required this.status,\n    this.appliedAt,\n    this.updatedAt,\n    this.job,\n    this.coverLetter,\n  });\n\n  factory JobApplication.fromJson(Map<String, dynamic> json) {\n    return JobApplication(\n      id: json['id'] ?? '',\n      status: json['status'] ?? 'applied',\n      appliedAt: json['created_at'] != null ? DateTime.parse(json['created_at']) : null,\n      updatedAt: json['updated_at'] != null ? DateTime.parse(json['updated_at']) : null,\n      job: json['job'] != null ? Job.fromJson(json['job']) : null,\n      coverLetter: json['cover_letter'],\n    );\n  }\n\n  Map<String, dynamic> toJson() {\n    return {\n      'id': id,\n      'status': status,\n      'created_at': appliedAt?.toIso8601String(),\n      'updated_at': updatedAt?.toIso8601String(),\n      'job': job?.toJson(),\n      'cover_letter': coverLetter,\n    };\n  }\n\n  Color get statusColor {\n    return switch (status) {\n      'hired' => Colors.green,\n      'shortlisted' => Colors.orange,\n      'reviewed' => Colors.blue,\n      'applied' => Colors.grey,\n      'rejected' => Colors.red,\n      _ => Colors.grey,\n    };\n  }\n\n  @override\n  List<Object?> get props => [id, status];\n}
